public void releaseShare(final Path file) {
  final String shareName;
  try {
    shareName = containerService.getContainer(file).getName();
    final ReentrantLock lock = locks.get(shareName);
    if (null == lock) {
      log.warn(String.format("Missing lock for %s", shareName));
      return;
    }
    if (log.isDebugEnabled()) {
      log.debug(String.format("Release lock for %s", shareName));
    }
    lock.unlock();
  } catch (NullPointerException e) {
    log.warn("Failed to release share due to null pointer", e);
  } catch (IllegalMonitorStateException e) {
    log.warn("Failed to release share due to illegal monitor state", e);
  }
}
